#!/usr/bin/env python3
"""Wave 23: the reduction mod p of the group generated by the invertible root-change blocks (3x3 on (H,E,lam)).
Enumerates the generated subgroup of GL3(F_p) by breadth-first search and compares with |GL3(F_p)|."""
import sys
B = {'J': ((1,-1,1),(1,-1,0),(1,0,1)), 'JOZ': ((3,-1,3),(1,0,0),(3,0,4)), 'JOOZ': ((5,-1,5),(1,0,0),(7,0,8)),
     'JOZZ': ((5,-1,7),(1,0,0),(5,0,8)), 'JOOOZ': ((9,-1,9),(1,0,0),(15,0,16)),
     'JOZOZ': ((9,-1,11),(1,0,0),(11,0,16)), 'JOZZZ': ((9,-1,15),(1,0,0),(9,0,16))}
def mul(A, C, p):
    return tuple(tuple(sum(A[i][k]*C[k][j] for k in range(3)) % p for j in range(3)) for i in range(3))
for p in map(int, sys.argv[1:] or ['3', '5']):
    gens = [tuple(tuple(x % p for x in row) for row in M) for M in B.values()]
    I = ((1,0,0),(0,1,0),(0,0,1))
    seen = {I}; frontier = [I]
    while frontier:
        nxt = []
        for X in frontier:
            for g in gens:
                Y = mul(X, g, p)
                if Y not in seen:
                    seen.add(Y); nxt.append(Y)
        frontier = nxt
    order = (p**3 - 1) * (p**3 - p) * (p**3 - p**2)
    print(f"p = {p}: generated subgroup has {len(seen)} elements; |GL3(F_{p})| = {order}; equal: {len(seen) == order}")
